      "slurm": "#!/bin/bash\n#SBATCH -p RM\n#SBATCH -t 48:00:00\n#SBATCH -N 8\n#SBATCH --ntasks-per-node 26\n#SBATCH -A phy210030p\n#SBATCH --mail-type=BEGIN,END,FAIL\n#SBATCH --mail-user=akshay2\n#SBATCH --output=/ocean/projects/phy210030p/akshay2/Slurm_logs/multi_acceljerk_%j.log\n\n# Ensure that the output directory to SBATCH exists prior to batch script execution.\nmodule load openmpi/3.1.6-gcc8.3.1\n\n# Define environment variables. $PROJECT = /ocean/projects/<group id>/<username>\nCMDDIR=$PROJECT/HPC_pulsar/cmd_files\n\necho $SLURM_NTASKS\n# Run acceleration searches within singularity container.\n$CMDDIR/multinode_accelsearch.cmd",
      "flux": "#!/bin/bash\n\n# Flux directives translated from SLURM\n#FLUX: -N 8\n#FLUX: -n 208\n#FLUX: -t 48:00:00\n#FLUX: -q RM\n#FLUX: -o /ocean/projects/phy210030p/akshay2/Slurm_logs/multi_acceljerk_%J.log\n\n#\n# --- Omitted SLURM options and explanations ---\n#\n# --ntasks-per-node 26\n#   The SLURM request for 8 nodes and 26 tasks per node is translated by specifying\n#   the total number of nodes (-N 8) and the total number of tasks (-n 208).\n#   Flux will distribute the 208 tasks evenly across the 8 nodes, resulting in\n#   the desired 26 tasks per node.\n#\n# -A phy210030p\n#   Omitted. Flux accounting is typically managed through system configuration or job\n#   submission options, not a standard batch directive.\n#\n# --mail-type=BEGIN,END,FAIL and --mail-user=akshay2\n#   Omitted. Flux core does not have built-in support for email notifications via\n#   batch directives. This functionality may be provided by site-specific\n#   plugins or wrappers.\n#\n\n# Ensure that the output directory to SBATCH exists prior to batch script execution.\nmodule load openmpi/3.1.6-gcc8.3.1\n\n# Define environment variables. $PROJECT = /ocean/projects/<group id>/<username>\n# The original script assumes $PROJECT is pre-set. This behavior is preserved.\nCMDDIR=$PROJECT/HPC_pulsar/cmd_files\n\n# The SLURM environment variable $SLURM_NTASKS is replaced by $FLUX_JOB_NTASKS\necho $FLUX_JOB_NTASKS\n\n# Run acceleration searches within singularity container.\n# IMPORTANT: The script being called, 'multinode_accelsearch.cmd', must use\n# a Flux-aware MPI launcher (e.g., 'flux run') to correctly start processes\n# on the allocated 208 tasks across 8 nodes.\n$CMDDIR/multinode_accelsearch.cmd\n",
