      "slurm": "#!/bin/bash\n#SBATCH -t 2-00:00:00\n#SBATCH -p gpu\n#SBATCH -c 12\n\n#Prepare python environment\nexport PYTHONPATH=$HOME/pythonpackages/lib/python:$PYTHONPATH\nexport PYTHONPATH=$HOME/pythonpackages/lib/python2.7/site-packages:$PYTHONPATH\nmodule load python/2.7.9\nmodule load cuda\nmodule load cudnn\n\n#Go to project folder\ncd $HOME/luna16/src/deep\n\n#Go!!!\n\necho \"starting python\"\nexport THEANO_FLAGS='mode=FAST_RUN,device=gpu,floatX=float32,lib.cnmem=1'\nsrun -u python train.py ../../config/resnet98_78.ini",
      "flux": "#!/bin/bash\n\n# Flux directives translated from SLURM\n#FLUX: -n 1\n#FLUX: -c 12\n#FLUX: -t 2-00:00:00\n#FLUX: -q gpu\n\n#\n# --- Omitted SLURM options and explanations ---\n#\n# GPU Request:\n#   The original script requests a 'gpu' partition and loads CUDA modules but does\n#   not explicitly request a GPU via '--gres'. This translation also omits an\n#   explicit GPU request. If a GPU is required, add '#FLUX: -g 1' to the directives.\n#   The 'THEANO_FLAGS' setting 'device=gpu' strongly suggests a GPU is needed.\n#   Performance implication: If the job is scheduled on a node without a GPU, the\n#   application will fail.\n#\n# Memory Request:\n#   The original SLURM script did not request a specific amount of memory. This job\n#   will receive the default memory allocation from the scheduler, which could\n#   be insufficient for this long-running GPU job and lead to an out-of-memory error.\n#\n\n#Prepare python environment\nexport PYTHONPATH=$HOME/pythonpackages/lib/python:$PYTHONPATH\nexport PYTHONPATH=$HOME/pythonpackages/lib/python2.7/site-packages:$PYTHONPATH\nmodule load python/2.7.9\nmodule load cuda\nmodule load cudnn\n\n#Go to project folder\ncd $HOME/luna16/src/deep\n\n#Go!!!\n\necho \"starting python\"\nexport THEANO_FLAGS='mode=FAST_RUN,device=gpu,floatX=float32,lib.cnmem=1'\n# The SLURM 'srun' command is replaced by 'flux run'.\nflux run -u python train.py ../../config/resnet98_78.ini\n",
